package dev.sablelife.client;
import dev.sablelife.SableLife;import dev.sablelife.module.*;import net.minecraft.client.gui.*;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;import net.minecraft.network.chat.Component;import net.minecraft.world.entity.player.Inventory;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.RegisterMenuScreensEvent;import net.neoforged.neoforge.network.PacketDistributor;import java.util.*;
@EventBusSubscriber(modid=SableLife.MOD_ID,bus=EventBusSubscriber.Bus.MOD,value=Dist.CLIENT)
public final class HealthPhaseRuleScreen extends AbstractContainerScreen<HealthPhaseRuleMenu> {
 private static final List<String> KEYS=List.of("phaseUpper","phaseLower","phaseChannel","phasePower","phasePulse");
 private final List<Button> list=new ArrayList<>(),apply=new ArrayList<>();private final List<EditBox> fields=new ArrayList<>();private List<HealthPhaseRules.Row> rules=List.of();private net.minecraft.nbt.ListTag last;private UUID selected;private int page,rows,column;private Button add,remove,up,down,enabled,mode,prev,next;
 public HealthPhaseRuleScreen(HealthPhaseRuleMenu menu,Inventory inv,Component title){super(menu,inv,title);}
 @SubscribeEvent public static void register(RegisterMenuScreensEvent e){e.register(SableLife.HEALTH_PHASE_RULE_MENU.get(),HealthPhaseRuleScreen::new);}
 private Component tr(String k){return Component.translatable("phase_rules.sablelife."+k);}private Button button(Component c,int x,int y,int w,Runnable r){return addRenderableWidget(LifeUiStyle.button(c,leftPos+x,topPos+y,w,18,r));}
 private HealthPhaseRules.Row current(){return rules.stream().filter(r->r.id().equals(selected)).findFirst().orElse(null);}private void send(String k,double v){PacketDistributor.sendToServer(new ModuleNetworking.Action(menu.containerId,menu.snapshot().getInt("Revision"),selected==null?new UUID(0,0):selected,"phase_rule_edit",k,v,""));}
 @Override protected void init(){imageWidth=Math.max(300,Math.min(480,width-12));imageHeight=Math.max(200,Math.min(400,height-12));super.init();list.clear();fields.clear();apply.clear();column=imageWidth/2;rows=Math.max(2,(imageHeight-112)/22);
  remove=button(tr("delete"),imageWidth-125,8,55,()->send("delete",0));button(tr("back"),imageWidth-65,8,55,()->minecraft.gameMode.handleInventoryButtonClick(menu.containerId,0));
  for(int i=0;i<rows;i++){final int n=i;list.add(button(Component.empty(),10,40+i*22,column-22,()->{int at=page*rows+n;if(at<rules.size()){selected=rules.get(at).id();fields.forEach(f->f.setFocused(false));sync();}}));}
  prev=button(Component.literal("<"),10,imageHeight-62,24,()->{page--;sync();});next=button(Component.literal(">"),column-36,imageHeight-62,24,()->{page++;sync();});add=button(tr("add"),10,imageHeight-38,column-70,()->send("add",0));up=button(Component.literal("↑"),column-56,imageHeight-38,20,()->send("up",0));down=button(Component.literal("↓"),column-33,imageHeight-38,20,()->send("down",0));
  int first=imageHeight<270?64:82,pitch=Math.min(38,(imageHeight-first-46)/4);int w=imageWidth-column-18;
  enabled=button(Component.empty(),column+8,34,w/2-2,()->{var r=current();if(r!=null)send("enabled",r.enabled()?0:1);});mode=button(Component.empty(),column+10+w/2,34,w/2-2,()->{var r=current();if(r!=null)send("phaseMode",1-r.value("phaseMode"));});
  for(int i=0;i<KEYS.size();i++){final int n=i;var f=addRenderableWidget(new EditBox(font,leftPos+column+8,topPos+first+i*pitch,w-34,18,tr(KEYS.get(i))));f.setMaxLength(12);f.setTooltip(Tooltip.create(tr("help")));fields.add(f);apply.add(button(Component.literal("✓"),imageWidth-36,first+i*pitch,26,()->apply(n)));}enabled.setTooltip(Tooltip.create(tr("help")));mode.setTooltip(Tooltip.create(tr("help")));sync();
 }
 private void apply(int i){try{double v=Double.parseDouble(fields.get(i).getValue());if(KEYS.get(i).equals("phasePulse"))v=Math.round(v*20);if(Double.isFinite(v)){send(KEYS.get(i),v);fields.get(i).setFocused(false);}}catch(NumberFormatException e){fields.get(i).setTextColor(0xFF7777);}}
 private void sync(){var data=menu.snapshot();var saved=data.getList("Groups",10);var before=rules;if(!saved.equals(last)){var c=new HealthPhaseRules();c.load(saved);rules=c.rows();boolean existed=last!=null;last=saved.copy();if(existed&&rules.size()>before.size()){selected=rules.getLast().id();page=(rules.size()-1)/rows;}}
  if(current()==null)selected=rules.isEmpty()?null:rules.getFirst().id();page=Math.clamp(page,0,Math.max(0,(rules.size()-1)/rows));
  for(int i=0;i<list.size();i++){int at=page*rows+i;var b=list.get(i);b.visible=at<rules.size();if(b.visible){var r=rules.get(at);var label=Component.literal((r.id().equals(selected)?"> ":"")+(at+1)+". "+String.format(Locale.ROOT,"%.1f–%.1f%%",r.value("phaseLower"),r.value("phaseUpper"))+" → "+(int)r.value("phaseChannel"));b.setMessage(label);b.setTooltip(Tooltip.create(label.copy().append(" · ").append(tr(r.enabled()?"enabled":"disabled"))));}}
  var r=current();boolean editable=data.getBoolean("Ready")&&data.getBoolean("Editable"),has=r!=null;add.active=editable&&rules.size()<HealthPhaseRules.LIMIT;remove.active=enabled.active=mode.active=editable&&has;up.active=editable&&has&&rules.indexOf(r)>0;down.active=editable&&has&&rules.indexOf(r)+1<rules.size();prev.active=page>0;next.active=(page+1)*rows<rules.size();enabled.setMessage(tr(has&&r.enabled()?"enabled":"disabled"));mode.setMessage(tr(has&&r.value("phaseMode")==1?"enter":"hold"));
  for(int i=0;i<fields.size();i++){var f=fields.get(i);String k=KEYS.get(i);f.active=apply.get(i).active=editable&&has&&(!k.equals("phasePulse")||r.value("phaseMode")==1);f.setEditable(f.active);if(!f.isFocused())f.setValue(has?String.format(Locale.ROOT,k.equals("phaseChannel")||k.equals("phasePower")?"%.0f":"%.2f",r.value(k)/(k.equals("phasePulse")?20:1)):"");}
 }
 @Override protected void containerTick(){super.containerTick();sync();}@Override public boolean keyPressed(int k,int scan,int mods){for(int i=0;i<fields.size();i++)if(fields.get(i).isFocused()&&k!=256){if(k==257||k==335){apply(i);return true;}return fields.get(i).keyPressed(k,scan,mods);}return super.keyPressed(k,scan,mods);}
 @Override public boolean mouseScrolled(double x,double y,double h,double v){for(int i=0;i<fields.size();i++){var f=fields.get(i);if(v!=0&&f.active&&f.isMouseOver(x,y)){double n;try{n=Double.parseDouble(f.getValue());}catch(NumberFormatException e){n=0;}String k=KEYS.get(i);double step=k.equals("phasePulse")?.1:1,min=k.equals("phasePower")?1:k.equals("phasePulse")?.05:0,max=k.equals("phaseChannel")?65535:k.equals("phasePower")?15:k.equals("phasePulse")?600:100;f.setValue(String.format(Locale.ROOT,"%.2f",Math.clamp(n+Math.signum(v)*step,min,max)));apply(i);return true;}}return super.mouseScrolled(x,y,h,v);}
 @Override protected void renderBg(GuiGraphics g,float p,int x,int y){g.fill(leftPos-2,topPos-2,leftPos+imageWidth+2,topPos+imageHeight+2,0xFF19151D);g.fill(leftPos,topPos,leftPos+imageWidth,topPos+imageHeight,0xFF9B614E);g.fill(leftPos+3,topPos+3,leftPos+imageWidth-3,topPos+imageHeight-3,0xFF242632);g.fill(leftPos+column-2,topPos+32,leftPos+column,topPos+imageHeight-7,0xFFAA79C8);}
 @Override protected void renderLabels(GuiGraphics g,int x,int y){g.drawString(font,tr("title"),10,13,0xE6D8EA,false);g.drawCenteredString(font,(page+1)+" / "+Math.max(1,(rules.size()+rows-1)/rows),column/2,imageHeight-57,0xD9C4ED);for(int i=0;i<fields.size();i++)g.drawString(font,tr(KEYS.get(i)),column+8,fields.get(i).getY()-topPos-11,0xD9C4ED,false);var r=current();if(r!=null){var status=Component.translatable("dashboard.sablelife.runtime_phase_waiting");if(r.value("phaseLower")>=r.value("phaseUpper"))status=Component.translatable("dashboard.sablelife.phase_invalid_range");else for(var item:menu.snapshot().getCompound("Runtime").getList("Rows",10)){var t=(net.minecraft.nbt.CompoundTag)item;if(t.hasUUID("Id")&&t.getUUID("Id").equals(r.id())){status=Component.translatable("dashboard.sablelife."+(t.getBoolean("Active")?"runtime_phase_active":!t.getString("ChannelStatus").equals("ready")?"phase_channel_"+t.getString("ChannelStatus"):"runtime_phase_waiting"));break;}}String text=font.plainSubstrByWidth(status.getString(),imageWidth-column-18);g.drawString(font,text,column+8,imageHeight-20,0xBDA5D0,false);}}
 @Override public void render(GuiGraphics g,int x,int y,float p){sync();renderBackground(g,x,y,p);super.render(g,x,y,p);renderTooltip(g,x,y);}
}
